#!/usr/bin/env bash
set -euo pipefail
cd /workspaces/TakeProp
git pull --rebase origin main
mkdir -p apps/web/app/terminal apps/web/app/api/trading supabase/migrations supabase/functions/sim-trading
printf '%s' '' | base64 -d > apps/web/app/terminal/page.tsx
printf '%s' '' | base64 -d > apps/web/app/terminal/terminal-client.tsx
printf '%s' '' | base64 -d > apps/web/app/terminal/terminal.module.css
printf '%s' '' | base64 -d > apps/web/app/api/trading/route.ts
printf '%s' '' | base64 -d > supabase/migrations/20260817130000_add_simulated_trading_risk_engine.sql
printf '%s' '' | base64 -d > supabase/functions/sim-trading/index.ts
python3 - <<'PY'
from pathlib import Path
p=Path("apps/web/app/dashboard/page.tsx")
s=p.read_text()
old='<button className="btn">Open terminal →</button>'
new='<Link className="btn" href="/terminal">Open terminal →</Link>'
if old not in s and new not in s:
    raise SystemExit("Dashboard terminal button pattern not found")
s=s.replace(old,new)
s=s.replace('<a>Trade</a>','<Link href="/terminal">Trade</Link>')
s=s.replace('<a>Orders &amp; positions</a>','<Link href="/terminal">Orders &amp; positions</Link>')
p.write_text(s)
PY
cat > supabase/migrations/20260817110000_allow_usdt_order_currency.sql <<'SQL'
alter table public.orders drop constraint if exists orders_currency_check;
alter table public.orders add constraint orders_currency_check check (currency in ('USD','USDT'));
SQL
pnpm --filter web build
git add apps/web/app/terminal apps/web/app/api/trading apps/web/app/dashboard/page.tsx supabase/migrations supabase/functions/sim-trading
if git diff --cached --quiet; then
  echo "No changes to commit."
  exit 0
fi
git commit -m "Add secure simulated trading terminal and risk engine"
git push origin main
echo "DONE — terminal published to main."

